/**
 * From 1.19.1 the overlay message is drawn with Font.drawShadow like the title, so the dialogue box is
 * rebuilt inside nyanlex$hud instead of a separate Font.draw redirect. This keeps the dialogue under its
 * own crash guard; a failure leaves the one-line action bar path in place.
 */
private static Component nyanlex$dialogue(Component text, Font font) {
    if (!HookGuard.enter("GuiScoreboard.overlayDialogue")) return null;
    try {
        return OverlayDialogueView.view(text, font);
    } catch (Throwable guardError) {
        HookGuard.fail("GuiScoreboard.overlayDialogue", guardError);
        return null;
    }
}

if (text == overlayMessageString) {
    Component dialogue = nyanlex$dialogue(text, font);
    if (dialogue != null) {
        return InternalRenderGuard.call(() -> font.drawShadow(pose, dialogue, x, y, color));
    }
}
if (service != null && text == overlayMessageString)
    return drawTranslated("actionBar", service::translateActionBar, font, pose, text, x, y, color);
